{
  "book_code": "JASHER",
  "verses": [
    {
      "chapter": 7,
      "verse": 51,
      "source_ref": "7:51",
      "text_ar": "كان عمر طرة سبعين سنة عندما أنجبه، فأسمى طرة ابنه المولود له إبراهيم، لأن الملك قد رباه في ذلك الوقت، ورفعه فوق جميع أمرائه الذين كانوا معه."
    },
    {
      "chapter": 8,
      "verse": 1,
      "source_ref": "8:1",
      "text_ar": "وكان ذلك في الليلة التي وُلد فيها إبراهيم، حيث جاء جميع خدم طرة، وجميع الحكماء من نمرد، وساحرونه، فأكلوا وشربوا في بيت طرة، وفرحوا معه في تلك الليلة."
    },
    {
      "chapter": 8,
      "verse": 2,
      "source_ref": "8:2",
      "text_ar": "وعندما خرج جميع الحكماء والساحرون من بيت طرة، رفعوا أعينهم إلى السماء تلك الليلة لينظروا إلى النجوم، فنظروا فظهر نجمٌ كبيرٌ جدًا جاء من الشرق وجرى في السماء، فابتلع الأربعة نجوم من الجهات الأربعة للسماء."
    },
    {
      "chapter": 8,
      "verse": 3,
      "source_ref": "8:3",
      "text_ar": "وأنهر جميع حكماء الملك وساحرونه من المشهد، وفهم الحكماء هذا الأمر، وعرفوا معناه."
    },
    {
      "chapter": 8,
      "verse": 4,
      "source_ref": "8:4",
      "text_ar": "وقالوا لبعضهم: هذا يدل فقط على الطفل الذي وُلد لطره هذه الليلة، الذي سيكبر ويُثمر، ويتكاثر، ويمتلك الأرض كلها، هو وأولاده إلى الأبد، هو وسلالته سيذبحون ملوكًا عظامًا، ويرثون أراضيهم."
    }
  ]
}
